-- N+1: 1 + 50 round trips
SELECT id, customer_id FROM orders WHERE product_id = 42;
-- then, per order, in a loop:
SELECT name FROM customers WHERE id = ?;

-- Batched: 2 round trips total
SELECT id, customer_id FROM orders WHERE product_id = 42;
SELECT id, name FROM customers
WHERE id IN (11, 12, 13, /* ...all 50 ids... */);
